const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const store={get:(k,d)=>{try{const v=localStorage.getItem('frostline_'+k);return v?JSON.parse(v):d}catch{return d}},set:(k,v)=>localStorage.setItem('frostline_'+k,JSON.stringify(v))};
// ── Fresh-install defaults (applied ONCE; existing installs untouched) ──
async function seedFreshDefaults(){try{
const S=(k,v)=>localStorage.setItem('frostline_'+k,JSON.stringify(v));
S('bg','unsplash');S('refresh','tab');
S('clock','rectangle');S('clockSize',130);S('timeFormat','12h');
S('vis',{date:1,weather:1,tasks:1,pomodoro:1,github:1,world:1,notes:1,news:1,dock:1,ai:1,quote:1,search:1});
S('mag',1);S('ui_gapps',1);S('ui_fs',1);
S('orbitGeom',{r:135,size:45,gap:55});S('geomV',3);
S('gh','');S('newsCountry','US');S('newsCat','general');S('holiday','General');
const DISC1={enabled:1,idle:15,grace:60,minTabs:3,neverActive:1,neverAudible:1,neverPinned:1,neverForm:1,whitelist:'',memPressure:0,memThreshold:20};
const DIM1={enabled:1,white:1,dark:0,vals:{dimmer:0,reader:0,blur:0},fx:{dimmer:1,reader:0,blur:0},edit:'dimmer',mode:'dimmer',scopes:{dimmer:'page',reader:'page',blur:'page'}};
const YT1={enabled:1,wfs:0,remember:1,shortcut:1};
S('discardCfg',DISC1);S('dimmerCfg',DIM1);S('ytCfg',YT1);
// Random rotation offset so a reset does not land on the same photo every
// time. Keep the bound in sync with KEYLESS_BG length. Existing installs have
// no key and keep offset 0, so their rotation is unchanged.
S('bgOffset',Math.floor(Math.random()*10));
S('onb',0);
try{if(chrome&&chrome.storage&&chrome.storage.local)await chrome.storage.local.set({frostline_discardCfg:DISC1,frostline_dimmerCfg:DIM1,frostline_ytCfg:YT1});}catch{}
try{localStorage.setItem('frostline_defaultsV','1');}catch{}
}catch{}}
try{
if(!localStorage.getItem('frostline_defaultsV')){
let hasReal=false;
for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(!k||k.indexOf('frostline_')!==0)continue;if(k==='frostline_defaultsV'||k==='frostline_onb')continue;if(/Migrated$/.test(k))continue;hasReal=true;break;}
if(!hasReal)seedFreshDefaults();else{try{localStorage.setItem('frostline_defaultsV','1');}catch{}}
}
}catch{}

let _ampmShown=null;
function isDigitalClock(){const c=document.body.dataset.clock;return c==='modern';}
function syncAmpm(){const show=isDigitalClock()&&store.get('timeFormat','12h')==='12h';if(show===_ampmShown)return;_ampmShown=show;const ap=$('#d-ampm');if(ap)ap.style.display=show?'inline':'none';}
function pulseClock(){const c=$('#clock-card');if(!c)return;c.style.animation='none';void c.offsetWidth;c.style.animation='';}
function applyClockSize(){const s=store.get('clockSize',100);const c=$('#clock-card');if(c){c.style.scale='';c.style.zoom=s/100;}const v=$('#clock-size-val');if(v)v.textContent=s+'%';const r=$('#set-clock-size');if(r&&+r.value!==s)r.value=s;}
// Clock + greeting + date
function tick(){
  const n=new Date();
  const h=n.getHours(), m=n.getMinutes();
  const degM=m*6, degH=(h%12)*30+m*0.5, degS=n.getSeconds()*6;
  $('#h-minute').style.transform=`rotate(${degM}deg)`;
  $('#h-hour').style.transform=`rotate(${degH}deg)`;
  const hs=$('#h-sec');if(hs)hs.style.transform=`rotate(${degS}deg)`;
  const mH=$('#m-hour'),mM=$('#m-minute'),mS=$('#m-sec');if(mH)mH.style.transform=`rotate(${degH}deg)`;if(mM)mM.style.transform=`rotate(${degM}deg)`;if(mS)mS.style.transform=`rotate(${degS}deg)`;
  const ra=$('#rect-arc');if(ra)ra.style.strokeDashoffset=String(100-(n.getSeconds()/60)*100);
  const greet=h<6?'Good night':h<12?'Good morning':h<17?'Good afternoon':'Good evening';
  const name=store.get('name','');
  const showG=store.get('showGreet',0), showC=store.get('showCustom',0), custom=store.get('customGreet','');
  const gEl=$('#greeting');
  if(!showG){gEl.style.display='none';}
  else{gEl.style.display='';gEl.textContent=(showC&&custom?custom:greet+(name?' '+name.toUpperCase():''));}
  const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
  $('#w-day-name').textContent=days[n.getDay()];
  $('#w-date').textContent=`${months[n.getMonth()]} ${n.getDate()}`;
  const tf=store.get('timeFormat','12h');const dh=$('#d-h'),dm=$('#d-m');if(dh)dh.textContent=tf==='24h'?String(h).padStart(2,'0'):String(h%12||12).padStart(2,'0');if(dm)dm.textContent=String(m).padStart(2,'0');
  const ap=$('#d-ampm');if(ap)ap.textContent=h>=12?'PM':'AM';syncAmpm();
}
setInterval(tick,1000);tick();
(function(){const an=$('#analog');if(!an||an.dataset.ticks)return;an.dataset.ticks='1';for(let i=0;i<12;i++){const q=i%3===0;const d=document.createElement('div');d.className='tick';const s=q?3:2;d.style.width=d.style.height=s+'px';d.style.background=q?'rgba(255,255,255,.85)':'rgba(255,255,255,.35)';d.style.transform=`translate(-50%,-50%) rotate(${i*30}deg) translateY(-88px)`;an.appendChild(d);}})();

