let taskEdit=null;
function renderTasks(){$('#task-list').innerHTML='';tasks.forEach((t)=>{const li=document.createElement('li');li.className=t.completed?'done':'';li.innerHTML=`<span class="tbox">${t.completed?'✓':''}</span><span class="txt"></span>`;li.querySelector('.tbox').onclick=e=>{e.stopPropagation();if(taskEdit)return;t.completed=!t.completed;store.set('tasks',tasks);renderTasks();};const tx=li.querySelector('.txt');if(taskEdit===t.id){const inp=document.createElement('textarea');inp.className='task-edit-input';inp.rows=1;inp.value=t.text;tx.appendChild(inp);const grow=()=>{inp.style.height='auto';inp.style.height=inp.scrollHeight+'px';};inp.oninput=()=>grow();grow();requestAnimationFrame(grow);inp.focus();try{inp.setSelectionRange(inp.value.length,inp.value.length);}catch{}const commit=save=>{if(inp.dataset.done)return;inp.dataset.done='1';if(save){const v=inp.value.trim();if(v)t.text=v;}taskEdit=null;store.set('tasks',tasks);renderTasks();};inp.onclick=e=>e.stopPropagation();inp.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();commit(true);}else if(e.key==='Escape')commit(false);};inp.title='Enter to save · Shift+Enter for new line · Esc to cancel';inp.onblur=()=>commit(true);}else tx.textContent=t.text;const pen=document.createElement('button');pen.className='task-pen flipx';pen.textContent='✎';pen.title='Edit';pen.onclick=e=>{e.stopPropagation();taskEdit=t.id;renderTasks();};li.appendChild(pen);const del=document.createElement('button');del.className='task-del';del.title='Delete';del.innerHTML='<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a1 1 0 011-1h6a1 1 0 011 1v2"/><path d="M19 6v14a2 2 0 01-2 2H7a2 2 0 01-2-2V6"/></svg>';del.onclick=e=>{e.stopPropagation();if(taskEdit===t.id)taskEdit=null;tasks=tasks.filter(x=>x.id!==t.id);store.set('tasks',tasks);renderTasks();};li.appendChild(del);li.onclick=()=>{if(taskEdit)return;li.classList.toggle('open');};$('#task-list').appendChild(li);});const open=tasks.filter(t=>!t.completed).length;$('#tasks-count').textContent=`${open} OPEN`;$('#w-tasks').textContent=open?`${open} pending`:'All done';}
$('#task-add-btn').onclick=()=>{const v=$('#task-input').value.trim();if(!v)return;tasks.push({id:String(Date.now()),text:v,completed:false,createdAt:Date.now()});$('#task-input').value='';store.set('tasks',tasks);renderTasks();};
$('#task-input').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#task-add-btn').click();}else if(e.key==='Escape'){e.stopPropagation();const f=$('#task-input');if(f.value)f.value='';else closeAll();}});
