// Simple timer (single session, H/M/S steppers, default 5:00)
let tm={left:store.get('pomoLeft',300),base:store.get('pomoBase',300),running:false,timer:null,endAt:0};
function pomoLeftNow(){return tm.running&&tm.endAt?Math.max(0,Math.ceil((tm.endAt-Date.now())/1000)):tm.left;}
function pomoWrite(){const p={base:tm.base,running:!!tm.running,endAt:tm.running&&tm.endAt?tm.endAt:0,left:pomoLeftNow()};store.set('pomo',p);store.set('pomoLeft',p.left);store.set('pomoBase',p.base);try{chrome.storage.local.set({frostline_pomo:p});}catch{}}
function fmtHMS(s){s=Math.max(0,Math.round(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60),ss=s%60;const mm=String(m).padStart(h?2:2,'0'),qq=String(ss).padStart(2,'0');return h?`${h}:${mm}:${qq}`:`${String(m).padStart(2,'0')}:${qq}`;}
function pomBeep(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const C=new AC();try{if(C.state==='suspended')C.resume();}catch{}[660,660,880].forEach((f,i)=>{const o=C.createOscillator(),g=C.createGain();o.connect(g);g.connect(C.destination);o.frequency.value=f;const t=C.currentTime+i*0.25;g.gain.setValueAtTime(0.15,t);g.gain.exponentialRampToValueAtTime(0.001,t+0.2);o.start(t);o.stop(t+0.2);});setTimeout(()=>C.close(),1200);}catch{}}
function drawTm(){const h=Math.floor(tm.left/3600),m=Math.floor(tm.left%3600/60),s=tm.left%60;$('#t-time').textContent=fmtHMS(tm.left);$('#t-fill').style.width=(tm.base?tm.left/tm.base*100:0)+'%';$('#t-play').textContent=tm.running?'⏸':'▶';$('#t-h').textContent=h;$('#t-m').textContent=m;$('#t-s').textContent=s;$('#w-focus').textContent=tm.running?'Focusing… '+fmtHMS(tm.left):(tm.left>0&&tm.left!==tm.base?'Paused':'Ready to focus?');}
function pomoClearTimer(){clearInterval(tm.timer);tm.timer=null;tm.running=false;tm.endAt=0;}
function pomoStart(){if(tm.running)return;if(tm.left<=0)tm.left=tm.base||300;tm.endAt=Date.now()+tm.left*1000;tm.running=true;tm.timer=setInterval(()=>{tm.left=pomoLeftNow();if(tm.left<=0){pomoComplete();return;}store.set('pomoLeft',tm.left);drawTm();},250);try{chrome.runtime.sendMessage({cmd:'pomo-start',endAt:tm.endAt});}catch{}pomoWrite();drawTm();}
function pomoPause(){if(tm.running){tm.left=pomoLeftNow();}pomoClearTimer();try{chrome.runtime.sendMessage({cmd:'pomo-stop'});}catch{}pomoWrite();drawTm();}
function pomoReset(){pomoClearTimer();try{chrome.runtime.sendMessage({cmd:'pomo-stop'});}catch{}tm.left=tm.base;pomoWrite();drawTm();}
function pomoComplete(){pomoClearTimer();tm.left=0;pomoWrite();drawTm();try{chrome.runtime.sendMessage({cmd:'pomo-stop'});}catch{}pomBeep();try{if(chrome.notifications){chrome.notifications.create({type:'basic',title:'Focus session complete',message:'Your Pomodoro session finished. Nice work!',iconUrl:chrome.runtime.getURL('assets/icon128.png'),silent:false});}}catch{}}
function stepTm(unit,d){pomoClearTimer();const p={h:Math.floor(tm.left/3600),m:Math.floor(tm.left%3600/60),s:tm.left%60};p[unit]=Math.min(99,Math.max(0,p[unit]+d));tm.left=tm.base=p.h*3600+p.m*60+p.s;pomoWrite();drawTm();}
$('#t-play').onclick=()=>{if(tm.running){pomoPause();}else{pomoStart();}};
$('#t-reset').onclick=()=>{pomoReset();};
let tSign=1,tHoldT=null,tHoldFired=false;
function syncTSign(){const b=$('#t-plus5');if(!b)return;b.textContent=tSign>0?'+5':'−5';b.title=tSign>0?'Add 5:00 per tap · hold to switch to −5':'Subtract 5:00 per tap · hold to switch to +5';}
$('#t-plus5').onclick=()=>{if(tHoldFired){tHoldFired=false;return;}const cap=99*3600+59*60+59;const cur=tm.running?pomoLeftNow():tm.left;if(tSign>0){tm.left=Math.min(cap,cur+300);tm.base=Math.min(cap,tm.base+300);}else{tm.left=Math.max(0,cur-300);tm.base=Math.max(0,tm.base-300);}tm.endAt=tm.running?Date.now()+tm.left*1000:0;pomoWrite();drawTm();};
$('#t-plus5').onpointerdown=()=>{clearTimeout(tHoldT);tHoldT=setTimeout(()=>{tSign*=-1;tHoldFired=true;syncTSign();tHoldT=null;},550);};
['pointerup','pointerleave','pointercancel'].forEach(ev=>$('#t-plus5').addEventListener(ev,()=>{clearTimeout(tHoldT);tHoldT=null;}));
syncTSign();
$$('.t-stepbtn').forEach(b=>b.onclick=()=>stepTm(b.dataset.u,+b.dataset.d));
try{chrome.runtime.onMessage.addListener((m)=>{if(m&&m.cmd==='pomo-beep'){try{pomBeep();}catch{}}});}catch{}
try{chrome.storage.onChanged.addListener((ch,area)=>{if(area!=='local'||!ch.frostline_pomo)return;const p=ch.frostline_pomo.newValue;if(!p)return;tm.base=+p.base||tm.base;if(p.running&&p.endAt){tm.running=true;tm.endAt=+p.endAt;tm.left=Math.max(0,Math.ceil((tm.endAt-Date.now())/1000));if(!tm.timer){tm.timer=setInterval(()=>{tm.left=pomoLeftNow();if(tm.left<=0){pomoComplete();return;}store.set('pomoLeft',tm.left);drawTm();},250);}}else{clearInterval(tm.timer);tm.timer=null;tm.running=false;tm.left=+(p.left||0);tm.endAt=0;}drawTm();});}catch{}
try{chrome.storage.local.get('frostline_pomo',(o)=>{try{const p=o&&o.frostline_pomo;if(!p)return;tm.base=+p.base||tm.base;if(p.running&&+p.endAt&&+p.endAt>Date.now()){tm.running=true;tm.endAt=+p.endAt;tm.left=Math.max(0,Math.ceil((tm.endAt-Date.now())/1000));tm.timer=setInterval(()=>{tm.left=pomoLeftNow();if(tm.left<=0){pomoComplete();return;}store.set('pomoLeft',tm.left);drawTm();},250);}drawTm();}catch{}});}catch{}
drawTm();

// GitHub live (public events, compare-enriched pushes, 12-week heatmap)
let ghUser=store.get('gh','gauravspam');
const ghCompareCache=new Map();
function ghBranch(ref){return (ref||'').replace(/^refs\/heads\//,'')||'main';}
function ghDayKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function ghCompare(repo,before,head){const k=`${repo}@${before}...${head}`;if(ghCompareCache.has(k))return ghCompareCache.get(k);try{const r=await fetch(`https://api.github.com/repos/${repo}/compare/${before}...${head}`,{headers:ghHeaders()});const j=r.ok?await r.json():null;ghCompareCache.set(k,j);if(ghCompareCache.size>60)ghCompareCache.delete(ghCompareCache.keys().next().value);return j;}catch{return null;}}
function ghCommitUrl(user,repo,sha){return (/^[0-9a-f]{7,}$/i.test(sha||''))?`https://github.com/${repo}/commit/${sha}`:`https://github.com/${repo}/commits`;}
function relTime(ts){try{const d=Date.now()-new Date(ts).getTime();if(!(d>=0))return'';const m=Math.floor(d/60000);if(m<1)return'just now';if(m<60)return m+'m ago';const dt=new Date(ts);const hh=String(dt.getHours()).padStart(2,'0'),mm=String(dt.getMinutes()).padStart(2,'0');const h=Math.floor(m/60);if(h<24)return `${hh}:${mm}`;const days=Math.floor(h/24);if(days<7)return days+'d ago';if(days<30){const w=Math.floor(days/7);return w+' week'+(w>1?'s':'')+' ago';}const mo=Math.floor(days/30);if(mo<12)return mo+' month'+(mo>1?'s':'')+' ago';const y=Math.floor(mo/12);return y+' year'+(y>1?'s':'')+' ago';}catch{return'';}}
async function loadGH(){const u=(ghUser||'').trim();const err=$('#gh-err');if(err){err.classList.add('hidden');err.textContent='';}const ul0=$('#gh-commits');if(!u){if(ul0)ul0.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">Enter your username to see live activity</li>';$('#w-github').textContent='All Caught Up';return;}try{if(ul0)ul0.innerHTML='<div class="gh-skel"></div><div class="gh-skel"></div><div class="gh-skel"></div>';let ev=null;const gc=store.get('ghCache',null);if(gc&&gc.user===u&&(Date.now()-gc.ts)<600000){ev=gc.ev;}else{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(u)}/events/public?per_page=30`,{headers:ghHeaders()});if(r.status===404)throw new Error('User not found');if(r.status===403)throw new Error('Rate limited — add a token in Settings → GitHub, or try again later');if(!r.ok)throw new Error('GitHub request failed');ev=await r.json();try{store.set('ghCache',{user:u,ts:Date.now(),ev});}catch{}}const pushes=ev.filter(e=>e.type==='PushEvent').slice(0,6);const enriched=[];for(const p of pushes){const commits=(p.payload&&p.payload.commits)||[];if(commits.length){commits.forEach(c=>enriched.push({repo:p.repo.name,msg:(c.message||'').split('\n')[0]||'Push',sha:c.sha||'',date:p.created_at}));}else{const n=(p.payload&&p.payload.size)||0;const b=p.payload&&p.payload.before,hd=p.payload&&p.payload.head;if(b&&hd&&!/^0+$/.test(b)){const cmp=await ghCompare(p.repo.name,b,hd);(cmp&&cmp.commits||[]).forEach(c=>enriched.push({repo:p.repo.name,msg:((c.commit&&c.commit.message)||'').split('\n')[0]||'Push',sha:c.sha||'',date:p.created_at}));if(!(cmp&&cmp.commits&&cmp.commits.length))enriched.push({repo:p.repo.name,msg:`Pushed ${n} commit${n===1?'':'s'} to ${ghBranch(p.payload.ref)}`,sha:'',date:p.created_at});}else if(n){enriched.push({repo:p.repo.name,msg:`Pushed ${n} commit${n===1?'':'s'} to ${ghBranch(p.payload&&p.payload.ref)}`,sha:'',date:p.created_at});}}}enriched.sort((a,b)=>new Date(b.date)-new Date(a.date));const repos=new Set(enriched.map(e=>e.repo)).size;$('#gh-total').textContent=enriched.length;$('#gh-streak').textContent=pushes.length;$('#gh-week').textContent=repos;const ul=$('#gh-commits');ul.innerHTML='';enriched.slice(0,3).forEach(e=>{const li=document.createElement('li');const a=document.createElement('a');a.href=ghCommitUrl(u,e.repo,e.sha);a.target='_blank';a.rel='noopener';const ic=document.createElement('span');ic.className='c-ico';ic.textContent='⤺';const dt=document.createElement('span');dt.className='c-date';dt.textContent=new Date(e.date).toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit'});const tx=document.createElement('span');tx.style.cssText='flex:1;min-width:0';const m=document.createElement('div');m.className='c-msg';m.textContent=e.msg||'(no message)';const rp=document.createElement('div');rp.className='c-repo';rp.textContent=e.repo;tx.appendChild(m);tx.appendChild(rp);const tm=document.createElement('span');tm.className='c-time';tm.textContent=relTime(e.date);a.appendChild(ic);a.appendChild(dt);a.appendChild(tx);a.appendChild(tm);li.appendChild(a);ul.appendChild(li);});if(!enriched.length)ul.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">No pushes in the last 90 days</li>';$('#gh-updated').textContent='· updated '+new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});$('#w-github').textContent='@'+u;await loadGhRepos();renderGhLangs();loadGhLife();await loadGhBranches();await loadGhRepoCommits();loadGhReadme();applyGhShow();}catch(e){if(err){err.textContent=String((e&&e.message)||e);err.classList.remove('hidden');}$('#w-github').textContent='All Caught Up';}}
function ghSyncInputs(){$('#gh-user-input').value=ghUser;const s=$('#gh-input');if(s)s.value=ghUser;const tk=$('#gh-token');if(tk){tk.value=store.get('ghToken','');tk.placeholder='••••••••••••••••••••••••';tk.classList.remove('invalid');}const tn=$('#gh-token-note');if(tn)tn.classList.add('hidden');}
ghSyncInputs();loadGH();
let ghSel=store.get('ghSel',{repo:'',branch:'',defBranch:''});
let ghReposCache=[];
function hideCsel(){$$('.cdrop').forEach(d=>d.classList.remove('open'));}
function positionCsel(btn,drop){const r=btn.getBoundingClientRect();const avail=window.innerHeight-r.bottom-18;const h=Math.min(250,Math.max(120,avail));let top=r.bottom+6;if(top+h>window.innerHeight-8)top=Math.max(8,window.innerHeight-8-h);drop.style.maxHeight=h+'px';drop.style.left=r.left+'px';drop.style.top=top+'px';drop.style.width=Math.max(r.width,180)+'px';}
document.addEventListener('scroll',e=>{if(e.target&&e.target.closest&&e.target.closest('.cdrop'))return;hideCsel();},true);
function cselBuild(btnId,items,cur,onPick){const btn=$('#'+btnId),drop=$('#'+btnId.replace('-btn','-drop'));if(!btn||!drop)return;btn.innerHTML='';const nm=document.createElement('span');const found=items.find(i=>i.value===cur);nm.textContent=found?found.label:'Select…';const ch=document.createElement('small');ch.textContent='▾';btn.appendChild(nm);btn.appendChild(ch);drop.innerHTML='';items.forEach(it=>{const li=document.createElement('li');li.textContent=it.label;li.title=it.value;if(it.value===cur)li.classList.add('on');li.onclick=e=>{e.stopPropagation();hideCsel();onPick(it.value);};drop.appendChild(li);});btn.onclick=e=>{e.stopPropagation();const was=drop.classList.contains('open');hideCsel();if(!was){if(drop.parentElement!==document.body)document.body.appendChild(drop);positionCsel(btn,drop);drop.classList.add('open');}};}
async function loadGhRepos(){try{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(ghUser)}/repos?per_page=100&sort=updated`,{headers:ghHeaders()});const j=r.ok?await r.json():[];ghReposCache=j;if(!j.some(x=>x.full_name===ghSel.repo)){ghSel.repo=(j[0]&&j[0].full_name)||'';ghSel.defBranch=(j[0]&&j[0].default_branch)||'main';}else{const cur=j.find(x=>x.full_name===ghSel.repo);if(cur)ghSel.defBranch=cur.default_branch||'main';}store.set('ghSel',ghSel);paintGhRepo();}catch{paintGhRepo();}}
function paintGhRepo(){cselBuild('gh-repo-btn',ghReposCache.map(x=>({value:x.full_name,label:x.name})),ghSel.repo,v=>{ghSel.repo=v;ghSel.branch='';store.set('ghSel',ghSel);paintGhRepo();loadGhBranches().then(()=>{renderGhLangs();loadGhRepoCommits();loadGhReadme();});});}
async function loadGhBranches(){try{paintGhBranch([]);if(!ghSel.repo)return;const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/branches?per_page=100`,{headers:ghHeaders()});const j=r.ok?await r.json():[];if(!j.some(x=>x.name===ghSel.branch))ghSel.branch=ghSel.defBranch||((j[0]&&j[0].name)||'');store.set('ghSel',ghSel);paintGhBranch(j.map(x=>x.name));}catch{paintGhBranch([]);}}
function paintGhBranch(names){cselBuild('gh-branch-btn',names.map(n=>({value:n,label:n})),ghSel.branch,v=>{ghSel.branch=v;store.set('ghSel',ghSel);paintGhBranch(names);loadGhRepoCommits();});}
async function loadGhRepoCommits(){const ul=$('#gh-commits');if(!ul||!ghSel.repo)return;ul.innerHTML='<div class="gh-skel"></div><div class="gh-skel"></div>';try{const br=ghSel.branch?`?sha=${encodeURIComponent(ghSel.branch)}&per_page=3`:'?per_page=3';const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/commits${br}`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();ul.innerHTML='';if(!j.length)ul.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">No commits on this branch</li>';j.forEach(c=>{const li=document.createElement('li');const a=document.createElement('a');a.href=(c.html_url)||`https://github.com/${ghSel.repo}/commits`;a.target='_blank';a.rel='noopener';const ic=document.createElement('span');ic.className='c-ico';ic.textContent='⤺';const dt=document.createElement('span');dt.className='c-date';try{dt.textContent=new Date(c.commit.author.date).toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit'});}catch{dt.textContent='';}const tx=document.createElement('span');tx.style.cssText='flex:1;min-width:0';const m=document.createElement('div');m.className='c-msg';m.textContent=((c.commit&&c.commit.message)||'(no message)').split('\n')[0];const rp=document.createElement('div');rp.className='c-repo';rp.textContent=(c.commit&&c.commit.author&&c.commit.author.name)||ghSel.repo;tx.appendChild(m);tx.appendChild(rp);const tm=document.createElement('span');tm.className='c-time';try{tm.textContent=relTime(c.commit.author.date);}catch{tm.textContent='';}a.appendChild(ic);a.appendChild(dt);a.appendChild(tx);a.appendChild(tm);li.appendChild(a);ul.appendChild(li);});const up2=$('#gh-updated');if(up2)up2.textContent=ghSel.branch?'· '+ghSel.branch:'';}catch{}}
document.addEventListener('click',e=>{if(!e.target.closest||(!e.target.closest('.csel')&&!e.target.closest('.cdrop')))hideCsel();});
window.addEventListener('scroll',()=>{hideCsel();},true);
function ghCommitUser(){const v=$('#gh-user-input').value.trim();if(v&&v!==ghUser){ghUser=v;store.set('gh',ghUser);ghSel={repo:'',branch:'',defBranch:''};store.set('ghSel',ghSel);}ghSyncInputs();loadGH();}
$('#gh-user-input').addEventListener('keydown',e=>{if(e.key==='Enter')ghCommitUser();});
$('#gh-user-input').addEventListener('blur',ghCommitUser);
$('#gh-open').onclick=()=>{if(ghUser)window.open('https://github.com/'+encodeURIComponent(ghUser),'_blank');};
$('#gh-refresh').onclick=()=>{store.set('ghCache',null);loadGH();};
$('#gh-save2').onclick=async()=>{const btn=$('#gh-save2');const markBad=msg=>{const tk=$('#gh-token');if(tk)tk.classList.add('invalid');const n=$('#gh-token-note');if(n){n.textContent=msg;n.classList.remove('hidden');}};const v=$('#gh-input').value.trim();if(v)ghUser=v;store.set('gh',ghUser);const t=$('#gh-token').value.trim(),cur=store.get('ghToken','');if(t!==cur){if(!t){store.set('ghToken','');}else{btn.textContent='Checking…';try{const r=await fetch('https://api.github.com/user',{headers:{Authorization:'token '+t}});if(r.status===401){markBad('Invalid token — check the value and try again.');btn.textContent='Save';return;}}catch{}store.set('ghToken',t);}}btn.textContent='Save';ghSyncInputs();loadGH();flashSaved(btn);};
(function(){const tk=$('#gh-token');if(tk)tk.oninput=()=>{tk.classList.remove('invalid');const n=$('#gh-token-note');if(n)n.classList.add('hidden');};})();
function ghHeaders(){const h={};const t=store.get('ghToken','');if(t)h.Authorization='token '+t;return h;}
function mdToText(md){return String(md||'').replace(/```[\s\S]*?```/g,' ').replace(/!\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/\[([^\]]*)\]\([^)]*\)/g,'$1').replace(/<[^>]+>/g,' ').replace(/^#{1,6}\s+/gm,'').replace(/(\*\*|__)(.*?)\1/g,'$2').replace(/(^|\W)\*([^*\n]+)\*/g,'$1$2').replace(/`([^`]+)`/g,'$1').replace(/^(\s*)[-*+]\s+/gm,'$1• ').replace(/^\s*\|.*$/gm,' ').replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();}
async function loadGhReadme(){const sec=$('#gh-notif-sec'),box=$('#gh-readme');if(!sec||!box)return;if(!ghSel.repo){sec.classList.add('hidden');return;}try{const r=await fetch(`https://api.github.com/repos/${ghSel.repo}/readme`,{headers:Object.assign({Accept:'application/vnd.github.raw'},ghHeaders())});if(r.status===404){box.textContent='No README found';if(store.get('ghShow',{}).readme!==0)sec.classList.remove('hidden');return;}if(!r.ok)throw 0;const md=await r.text();box.textContent=mdToText(md).slice(0,1500);if(store.get('ghShow',{}).readme!==0)sec.classList.remove('hidden');}catch{sec.classList.add('hidden');}}
function syncTfSeg(){[...document.querySelectorAll('#tf-seg button')].forEach(b=>b.classList.toggle('on',b.dataset.tf===store.get('timeFormat','12h')));}
$$('#tf-seg button').forEach(b=>b.onclick=()=>{store.set('timeFormat',b.dataset.tf);syncTfSeg();tick();});
function shade(hex,f){let h=String(hex).replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16)||0;const r=Math.round(((n>>16)&255)*f),g=Math.round(((n>>8)&255)*f),b=Math.round((n&255)*f);return `rgb(${r},${g},${b})`;}
async function loadGhLife(){const box=$('#gh-life');if(!box)return;const t=store.get('ghToken','');if(!t||!ghUser){box.classList.add('hidden');return;}try{let cal=null;const c=store.get('ghLife',null);if(c&&c.user===ghUser&&(Date.now()-c.ts)<864e5)cal=c.cal;else{const r=await fetch('https://api.github.com/graphql',{method:'POST',headers:{Authorization:'bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({query:'query($login:String!){user(login:$login){contributionsCollection{contributionCalendar{totalContributions weeks{contributionDays{contributionCount date}}}}}}',variables:{login:ghUser}})});if(!r.ok)throw 0;const j=await r.json();cal=j.data&&j.data.user&&j.data.user.contributionsCollection&&j.data.user.contributionsCollection.contributionCalendar;if(!cal)throw 0;try{store.set('ghLife',{user:ghUser,ts:Date.now(),cal});}catch{}}const days=[];cal.weeks.forEach(w=>w.contributionDays.forEach(d=>days.push(d)));const total=cal.totalContributions||0;const todayK=new Date().toISOString().slice(0,10);let streak=0;for(let i=days.length-1;i>=0;i--){if(days[i].contributionCount>0)streak++;else{if(days[i].date>=todayK)continue;break;}}$('#gh-life-total').textContent=Number(total).toLocaleString();$('#gh-life-streak').textContent=streak;box.classList.remove('hidden');}catch{box.classList.add('hidden');}}
function renderGhToggles(){const t=$('#gh-toggles');if(!t)return;let s=store.get('ghShow',null);if(!s)s={stats:1,lang:1,commits:1,readme:1};else{if(s.c!==undefined){s.lang=s.c?1:0;delete s.c;}if(s.a!==undefined){s.commits=s.a?1:0;delete s.a;}['stats','lang','commits','readme'].forEach(k=>{if(s[k]===undefined)s[k]=1;});store.set('ghShow',s);}t.innerHTML='';[['stats','Show Stats Row'],['lang','Show Languages Chart'],['commits','Show Recent Commits'],['readme','Show README']].forEach(([k,label])=>{t.appendChild(toggleRow(label,s[k],()=>{s[k]=s[k]?0:1;store.set('ghShow',s);renderGhToggles();applyGhShow();}));});}
const GH_LANG_COLORS={JavaScript:'#f1e05a',TypeScript:'#3178c6',Python:'#3572A5',Java:'#b07219',HTML:'#e34c26',CSS:'#563d7c',Go:'#00ADD8',Rust:'#dea584',Ruby:'#701516',PHP:'#4F5D95',C:'#555555','C++':'#f34b7d','C#':'#178600',Swift:'#F05138',Kotlin:'#A97BFF',Dart:'#00B4AB',Shell:'#89e051',PowerShell:'#5391FE',Vue:'#41b883',Svelte:'#ff3e00',Lua:'#000080',R:'#198CE7',Scala:'#c22d40',Haskell:'#5e5086',Elixir:'#6e4a7e',Zig:'#ec915c',Dockerfile:'#384d54','Jupyter Notebook':'#DA5B0B',TeX:'#3D6117','Vim Script':'#019733'};
async function loadGhLangBytes(){const cached=store.get('ghLangs',null);if(cached&&cached.user===ghUser&&(Date.now()-cached.ts)<864e5&&cached.map)return cached.map;const map={};await Promise.all(ghReposCache.map(async x=>{try{const r=await fetch(`https://api.github.com/repos/${x.full_name}/languages`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();Object.entries(j).forEach(([l,b])=>{map[l]=(map[l]||0)+b;});}catch{}}));if(!Object.keys(map).length)throw 0;try{store.set('ghLangs',{user:ghUser,ts:Date.now(),map});}catch{}return map;}
async function loadGhRepoLangs(repo){const c=store.get('ghLangRepo',null);if(c&&c.repo===repo&&(Date.now()-c.ts)<864e5&&c.map)return c.map;const r=await fetch(`https://api.github.com/repos/${repo}/languages`,{headers:ghHeaders()});if(!r.ok)throw 0;const j=await r.json();if(!Object.keys(j).length)throw 0;try{store.set('ghLangRepo',{repo,ts:Date.now(),map:j});}catch{}return j;}
async function renderGhLangs(){const bar=$('#gh-langbar'),list=$('#gh-langlist');if(!bar||!list)return;const counts={},byLang={};ghReposCache.forEach(x=>{let l=x.language||'Other';if(!String(l).trim())l='Other';counts[l]=(counts[l]||0)+1;(byLang[l]=byLang[l]||[]).push(x.name);});let rows=null,tot=0;const cap=$('#gh-cap');try{let bytes=null;if(ghSel.repo){try{bytes=await loadGhRepoLangs(ghSel.repo);}catch{bytes=null;}if(cap)cap.textContent='languages · '+((ghSel.repo||'').split('/')[1]||ghSel.repo);if(!bytes||!Object.keys(bytes).length){bar.innerHTML='';list.innerHTML='<li style="opacity:.55;font-size:13px">No languages detected</li>';return;}}else{if(cap)cap.textContent='languages across public repos';bytes=await loadGhLangBytes();}rows=Object.entries(bytes).sort((a,b)=>b[1]-a[1]).slice(0,6);tot=Math.max(1,rows.reduce((a,[,b])=>a+b,0));}catch{rows=Object.entries(counts).filter(([l])=>l!=='Other').sort((a,b)=>b[1]-a[1]).slice(0,6);tot=Math.max(1,rows.reduce((a,[,b])=>a+b,0));}bar.innerHTML='';list.innerHTML='';if(!rows.length){list.innerHTML='<li style="opacity:.55;font-size:13px">No languages detected</li>';return;}const CX=150,CY=82,RR=64,RK=0.55,DD=16,NS='http://www.w3.org/2000/svg';
const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 300 190');svg.setAttribute('width','100%');svg.innerHTML=`<defs><filter id="pieBlur" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="7"/></filter></defs><ellipse cx="${CX}" cy="${CY+DD+12}" rx="${RR+8}" ry="17" fill="rgba(0,0,0,.4)" filter="url(#pieBlur)"/>`;
const slices=[];let ang=-Math.PI/2;
rows.forEach(([l,n])=>{const frac=n/tot,a0=ang,a1=ang+frac*Math.PI*2;ang=a1;slices.push({l,n,frac,a0,a1});});
const repoTip=l=>((byLang[l]||[]).join(', '));
const shade=(hex,f)=>{let h=String(hex).replace('#','');if(h.length===3)h=h.split('').map(c=>c+c).join('');const n=parseInt(h,16)||0;const r=Math.round(((n>>16)&255)*f),g=Math.round(((n>>8)&255)*f),b=Math.round((n&255)*f);return `rgb(${r},${g},${b})`;};
const RRY=(RR*RK).toFixed(1);
const drawSlice=s=>{const col=GH_LANG_COLORS[s.l]||'#8b949e';const large=(s.a1-s.a0)>Math.PI?1:0;const x0=CX+RR*Math.cos(s.a0),y0=CY+RR*RK*Math.sin(s.a0),x1=CX+RR*Math.cos(s.a1),y1=CY+RR*RK*Math.sin(s.a1);const w=document.createElementNS(NS,'path');w.setAttribute('d',`M ${x0.toFixed(1)} ${y0.toFixed(1)} A ${RR} ${RRY} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)} L ${x1.toFixed(1)} ${(y1+DD).toFixed(1)} A ${RR} ${RRY} 0 ${large} 0 ${x0.toFixed(1)} ${(y0+DD).toFixed(1)} Z`);w.setAttribute('fill',shade(col,0.5));svg.appendChild(w);const p=document.createElementNS(NS,'path');p.setAttribute('d',`M ${CX} ${CY} L ${x0.toFixed(1)} ${y0.toFixed(1)} A ${RR} ${RRY} 0 ${large} 1 ${x1.toFixed(1)} ${y1.toFixed(1)} Z`);p.setAttribute('fill',col);const t=document.createElementNS(NS,'title');const rt=repoTip(s.l);t.textContent=`${s.l} — ${(s.frac*100).toFixed(0)}%`+(rt?` · ${rt}`:'');p.appendChild(t);svg.appendChild(p);};
if(slices.length===1){const col=GH_LANG_COLORS[slices[0].l]||'#8b949e';const eb=document.createElementNS(NS,'ellipse');eb.setAttribute('cx',CX);eb.setAttribute('cy',CY+DD);eb.setAttribute('rx',RR);eb.setAttribute('ry',RR*RK);eb.setAttribute('fill',shade(col,0.5));svg.appendChild(eb);const et=document.createElementNS(NS,'ellipse');et.setAttribute('cx',CX);et.setAttribute('cy',CY);et.setAttribute('rx',RR);et.setAttribute('ry',RR*RK);et.setAttribute('fill',col);const t=document.createElementNS(NS,'title');t.textContent=`${slices[0].l} — 100%`;et.appendChild(t);svg.appendChild(et);}else{[...slices].sort((a,b)=>Math.sin((a.a0+a.a1)/2)-Math.sin((b.a0+b.a1)/2)).forEach(drawSlice);}
bar.appendChild(svg);
const FS=9,GAP=13,TOP=12,BOT=150;const allLy=[CY+DD+29];
[[1],[-1]].forEach(([sgn])=>{const items=slices.filter(s=>sgn>0?Math.cos((s.a0+s.a1)/2)>=-0.08:Math.cos((s.a0+s.a1)/2)<-0.08).map(s=>({s,y:CY+RR*Math.sin((s.a0+s.a1)/2)}));items.sort((a,b)=>a.y-b.y);const ys=items.map(o=>o.y);for(let i=1;i<ys.length;i++)ys[i]=Math.max(ys[i],ys[i-1]+GAP);if(ys.length){const over=ys[ys.length-1]-BOT;if(over>0)for(let i=0;i<ys.length;i++)ys[i]-=over;if(ys[0]<TOP){const sh=TOP-ys[0];for(let i=0;i<ys.length;i++)ys[i]+=sh;}}items.forEach((o,i)=>{const mid=(o.s.a0+o.s.a1)/2;const ex=CX+RR*Math.cos(mid),ey=CY+RR*RK*Math.sin(mid);const ly=ys[i];allLy.push(ly);const lx=sgn>0?224:76,jx=sgn>0?218:82;const ln=document.createElementNS(NS,'line');ln.setAttribute('x1',ex.toFixed(1));ln.setAttribute('y1',ey.toFixed(1));ln.setAttribute('x2',jx);ln.setAttribute('y2',ly.toFixed(1));ln.setAttribute('stroke','rgba(255,255,255,.35)');ln.setAttribute('stroke-width','1');svg.appendChild(ln);const tx=document.createElementNS(NS,'text');tx.setAttribute('x',lx);tx.setAttribute('y',(ly+4).toFixed(1));tx.setAttribute('text-anchor',sgn>0?'start':'end');tx.setAttribute('font-size',FS);tx.setAttribute('fill','rgba(255,255,255,.75)');tx.textContent=o.s.l;svg.appendChild(tx);});});svg.setAttribute('viewBox',`0 0 300 ${Math.min(200,Math.max(...allLy)+10)}`);}
function applyGhShow(){const s=Object.assign({stats:1,lang:1,commits:1,readme:1},store.get('ghShow',{}));const show=(id,on)=>{const e=$('#'+id);if(e)e.style.display=on?'':'none';};show('gh-statsrow',s.stats);['gh-langbar','gh-langlist','gh-cap'].forEach(id=>show(id,s.lang));['gh-commlabel','gh-commits'].forEach(id=>show(id,s.commits));show('gh-notif-sec',s.readme);}
