const WX_KNOWN={mumbai:[19.07,72.87],thane:[19.2,72.97],delhi:[28.61,77.23],'new delhi':[28.61,77.23],bangalore:[12.97,77.59],bengaluru:[12.97,77.59],chennai:[13.08,80.27],kolkata:[22.57,88.36],hyderabad:[17.38,78.48],pune:[18.52,73.85],london:[51.5,-0.12],paris:[48.85,2.35],'new york':[40.71,-74.0],tokyo:[35.68,139.69],singapore:[1.35,103.82],dubai:[25.2,55.27],sydney:[-33.87,151.21]};
let wx=Object.assign({city:'Thane',unit:'c',mode:'city'},store.get('weather',{}));
function wxGeo(){return new Promise((res,rej)=>{if(!navigator.geolocation)return rej(new Error('no geo'));const t=setTimeout(()=>rej(new Error('timeout')),8000);navigator.geolocation.getCurrentPosition(p=>{clearTimeout(t);res(p);},e=>{clearTimeout(t);rej(e);});});}
function wxToU(c){return wx.unit==='f'?Math.round(c*9/5+32):Math.round(c);}
function wxDesc(c){return c===0?'Clear':c<=3?'Cloudy':c<=48?'Foggy':c<=67?'Rain':c<=77?'Snow':'Storm';}
function wxFmtSun(iso){if(!iso)return'';const d=new Date(iso);let h=d.getHours();const m=String(d.getMinutes()).padStart(2,'0');const ap=h>=12?'p':'a';h=h%12||12;return `${h}:${m}${ap}`;}
async function wxResolve(city){if((wx.mode||'city')==='auto'){try{const p=await wxGeo();return{lat:p.coords.latitude,lon:p.coords.longitude,name:'Local'};}catch{/* fall through to saved city */}}const q=(city||'').trim();const k=q.toLowerCase();if(WX_KNOWN[k])return{lat:WX_KNOWN[k][0],lon:WX_KNOWN[k][1],name:q};const m=q.match(/^(-?\d+\.?\d*)[,\s]+(-?\d+\.?\d*)$/);if(m){const la=parseFloat(m[1]),lo=parseFloat(m[2]);if(Math.abs(la)<=90&&Math.abs(lo)<=180)return{lat:la,lon:lo,name:`${la.toFixed(2)}°, ${lo.toFixed(2)}°`};}const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=1`);const j=await r.json();if(j.results&&j.results[0])return{lat:j.results[0].latitude,lon:j.results[0].longitude,name:j.results[0].name};throw new Error('nf');}
let wxAbort=null;
let wxCommitted=false,wxDropTimer=null,wxAbortDrop=null;
function hideWxDrop(){const d=$('#wx-drop');if(d)d.classList.remove('open');}
function positionWxDrop(){const ul=$('#wx-drop'),inp=$('#wx-input');if(!ul||!inp)return;const r=inp.getBoundingClientRect();ul.style.left=r.left+'px';ul.style.top=(r.bottom+6)+'px';ul.style.width=r.width+'px';}
function renderWxDrop(){const ul=$('#wx-drop');if(!ul)return;const q=($('#wx-input').value||'').trim();ul.innerHTML='';ul.classList.remove('open');if(q.length<2)return;clearTimeout(wxDropTimer);wxDropTimer=setTimeout(async()=>{try{if(wxAbortDrop)wxAbortDrop.abort();wxAbortDrop=new AbortController();const items=[];const ql=q.toLowerCase();const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(q)}&count=10`,{signal:wxAbortDrop.signal});const j=await r.json();(j.results||[]).forEach(x=>{const key=(x.name+'|'+(x.admin1||'')).toLowerCase();if(items.some(i=>i.key===key))return;const nl=(x.name||'').toLowerCase();const rank=nl.startsWith(ql)?0:nl.includes(ql)?1:2;items.push({name:x.name,sub:[x.admin1,x.country].filter(Boolean).join(', '),city:x.name,key:key,rank});});items.sort((a,b)=>a.rank-b.rank);ul.innerHTML='';items.slice(0,8).forEach(it=>{const li=document.createElement('li');const nm=document.createElement('span');nm.textContent=it.name;const sm=document.createElement('small');sm.textContent=it.sub;li.appendChild(nm);li.appendChild(sm);li.onclick=()=>{wx.city=it.city;store.set('weather',wx);wxSync();wxCommitted=true;loadWeather();};ul.appendChild(li);});if(items.length){ul.classList.add('open');positionWxDrop();}}catch(e){if(e&&e.name==='AbortError')return;}},300);}
document.addEventListener('click',e=>{const ul=$('#wx-drop');if(ul&&ul.classList.contains('open')&&!e.target.closest('#wx-searchrow')&&!e.target.closest('#wx-drop'))hideWxDrop();});
window.addEventListener('resize',()=>{const ul=$('#wx-drop');if(ul&&ul.classList.contains('open'))positionWxDrop();});
window.addEventListener('scroll',()=>{const ul=$('#wx-drop');if(ul&&ul.classList.contains('open'))positionWxDrop();},true);
function wxIsNight(j){try{const r=new Date(j.daily.sunrise[0]),s=new Date(j.daily.sunset[0]),n=new Date();return n<r||n>s;}catch{return false;}}
