let calSel=null;
function renderSel(){const box=$('#cal-sel');if(!box)return;if(!calSel){box.classList.add('hidden');box.innerHTML='';return;}const y=calCursor.getFullYear();const H=calHolidays(store.get('holiday','India'),y);const list=H.filter(h=>h.m===calSel.m&&h.d===calSel.d);if(!list.length){box.classList.add('hidden');box.innerHTML='';return;}const dt=new Date(y,calSel.m,calSel.d);box.classList.remove('hidden');box.innerHTML='';const t=document.createElement('div');t.className='sel-date';t.textContent=`${dt.toLocaleDateString('en-US',{month:'long',day:'numeric'})} · ${dt.toLocaleDateString('en-US',{weekday:'long'})}`;box.appendChild(t);list.forEach(h=>{const li=document.createElement('li');li.style.listStyle='none';const s=document.createElement('span');s.textContent=`${h.icon||'🎉'} ${h.name}`;li.appendChild(s);box.appendChild(li);});}
function renderCal(){const y=calCursor.getFullYear(),m=calCursor.getMonth();const today=new Date();const isCur=y===today.getFullYear()&&m===today.getMonth();$('#cal-title').innerHTML=`${calCursor.toLocaleString('en',{month:'long'})} <span>${y}</span>`;const start=new Date(y,0,1);const doy=Math.floor((today-start)/864e5)+1;const diy=((y%4===0&&y%100!==0)||y%400===0)?366:365;$('#cal-sub').textContent=`${today.toLocaleDateString('en-US',{weekday:'long'})} the ${calOrdinal(today.getDate())} · Week ${calIsoWeek(today)} · Day ${doy} · ${diy-doy} left`;{const dimM=new Date(y,m+1,0).getDate(),nowM=today.getMonth(),nowY=today.getFullYear();let frac;if(y<nowY||(y===nowY&&m<nowM))frac=1;else if(y===nowY&&m===nowM)frac=today.getDate()/dimM;else frac=0;$('#cal-progress i').style.width=(frac*100)+'%';}const dim=new Date(y,m+1,0).getDate(),first=new Date(y,m,1).getDay(),prevDim=new Date(y,m,0).getDate();const H=calHolidays(store.get('holiday','India'),y);const keys=new Set(H.map(h=>`${h.m}-${h.d}`));let h=['S','M','T','W','T','F','S'].map(d=>`<span class="wd">${d}</span>`).join('');const cells=[];for(let i=first-1;i>=0;i--)cells.push({d:prevDim-i,out:true,mm:(m+11)%12});for(let d=1;d<=dim;d++)cells.push({d,out:false,mm:m});let nd=1;while(cells.length<42)cells.push({d:nd++,out:true,mm:(m+1)%12});cells.forEach(c=>{const hol=keys.has(`${c.mm}-${c.d}`);const tod=!c.out&&isCur&&c.d===today.getDate();h+=`<span data-mm="${c.mm}" data-d="${c.d}" class="${c.out?'out':''}${tod?' today':''}${hol&&!tod?' hol':''}${(!c.out&&calSel&&calSel.m===c.mm&&calSel.d===c.d)?' sel':''}">${c.d}</span>`;});$('#cal-grid').innerHTML=h;const t0=new Date();t0.setHours(0,0,0,0);const isCurView=y===t0.getFullYear()&&m===t0.getMonth();const up=H.map(x=>({...x,dt:new Date(y,x.m,x.d)})).filter(x=>isCurView?x.dt>=t0:x.dt.getMonth()===m).sort((a,b)=>a.dt-b.dt).slice(0,isCurView?3:6);const ul=$('#cal-coming');ul.innerHTML=`<div class="cup-label">${isCurView?'Coming up':calCursor.toLocaleString('en',{month:'long'})+' holidays'}</div>`;if(!up.length)ul.innerHTML+='<li class="muted">Nothing coming up</li>';up.forEach(x=>{const diff=Math.round((x.dt-t0)/864e5);const li=document.createElement('li');const nm=document.createElement('span');nm.className='hol-row';const hi=document.createElement('span');hi.className='hol-ic';hi.textContent=x.icon||'🎉';const hn=document.createElement('span');hn.textContent=x.name;nm.appendChild(hi);nm.appendChild(hn);const sm=document.createElement('small');const lbl=x.dt.toLocaleDateString('en-US',{month:'short',day:'numeric'});sm.textContent=`${lbl} · ${diff===0?'today':diff>0?`in ${diff} day${diff===1?'':'s'}`:`${-diff} day${diff===-1?'':'s'} ago`}`;li.appendChild(nm);li.appendChild(sm);ul.appendChild(li);});renderSel();}
$('#cal-prev').onclick=()=>{calCursor.setMonth(calCursor.getMonth()-1);calSel=null;renderCal();renderSel();};
$('#cal-next').onclick=()=>{calCursor.setMonth(calCursor.getMonth()+1);calSel=null;renderCal();renderSel();};
$('#cal-grid').onclick=e=>{const s=e.target.closest('span[data-d]');if(!s||s.classList.contains('out'))return;calSel={m:+s.dataset.mm,d:+s.dataset.d};renderCal();renderSel();};
renderCal();

// Dock (stored shortcuts, magnification, right-click edit, shortcuts modal)
function seedShortcuts(){return $$('#dock a.dock-btn').map((a,i)=>({id:String(Date.now()+i),name:a.dataset.name||`Link ${i+1}`,url:a.dataset.url||a.href,cls:(a.querySelector('.gicon')||{}).className?String(a.querySelector('.gicon').className).replace('gicon','').trim():''}));}
let shortcuts=store.get('shortcuts',null);
if(!Array.isArray(shortcuts)||!shortcuts.length){shortcuts=seedShortcuts();store.set('shortcuts',shortcuts);}
function favHost(u){try{return new URL(u).hostname;}catch{return'';}}

function favAlias(h){h=(h||'').toLowerCase();if(h==='gmail.com'||h==='googlemail.com')return 'mail.google.com';if(h==='youtu.be'||h==='m.youtube.com')return 'youtube.com';if(h==='chatgpt.com')return 'chat.openai.com';return h;}
function favChain(h){h=favAlias(h);const s2='https://www.google.com/s2/favicons?domain='+h+'&sz=128';const ddg='https://icons.duckduckgo.com/ip3/'+h+'.ico';const direct='https://'+h+'/favicon.ico';if(h==='copilot.microsoft.com')return['https://copilot.microsoft.com/static/cmc/favicon.svg'];if(h==='gemini.google.com')return[s2];if(h==='deepseek.com'||h==='chat.deepseek.com')return['https://icons.duckduckgo.com/ip3/deepseek.com.ico','https://deepseek.com/favicon.ico',s2];if(h==='mail.google.com')return['https://mail.google.com/favicon.ico','https://icons.duckduckgo.com/ip3/mail.google.com.ico'];if(h==='claude.ai')return[s2,ddg];if(h==='perplexity.ai')return['https://www.perplexity.ai/favicon.svg',s2,ddg];if(h==='grok.com')return['https://grok.com/images/favicon.svg',s2,ddg];return[s2,ddg,direct];}
function favImgEl(h,onOk,onDead){const list=favChain(h);const img=new Image();img.loading='lazy';img.decoding='async';img.alt='';let i=0;img.src=list[0];img.addEventListener('load',()=>{if(onOk)onOk();});img.addEventListener('error',()=>{i++;if(i<list.length)img.src=list[i];else{img.remove();if(onDead)onDead();}});return img;}
function paintIcon(box,name,url,letterCls){box.textContent='';const s=document.createElement('span');if(letterCls)s.className=letterCls;s.textContent=(name||'?').trim().charAt(0).toUpperCase();box.appendChild(s);const h=favHost(url);if(h){const nm=(name||'').trim().toLowerCase();const im=/^gmail(\s|$)/.test(nm)?favImgEl('mail.google.com',()=>{s.style.display='none';},()=>{s.style.display='';}):favImgEl(h,()=>{s.style.display='none';},()=>{s.style.display='';});box.appendChild(im);}return box;}
function dockIconEl(s){const g=document.createElement('span');g.className='gicon '+(s.cls||'grid');paintIcon(g,s.name,s.url,'');return g;}
function renderDock(){const dock=$('#dock');dock.querySelectorAll('a.dock-btn').forEach(a=>a.remove());shortcuts.slice(0,12).forEach(s=>{const a=document.createElement('a');a.href=s.url;a.className='dock-btn';a.dataset.name=s.name;a.dataset.url=s.url;a.dataset.id=s.id;a.rel='noopener';a.appendChild(dockIconEl(s));dock.insertBefore(a,$('#dock-grid'));bindDockBtn(a);});renderShortcutsList();}
function bindDockBtn(b){b.addEventListener('mouseenter',()=>{const t=$('#tooltip');t.textContent=b.dataset.name||'App';t.classList.remove('hidden');const p=$('#url-preview');if(b.dataset.url){p.textContent=b.dataset.url;p.classList.remove('hidden');}});b.addEventListener('mouseleave',()=>{$('#tooltip').classList.add('hidden');$('#url-preview').classList.add('hidden');});b.addEventListener('contextmenu',e=>{e.preventDefault();const s=shortcuts.find(x=>x.id===b.dataset.id);if(!s)return;const nn=prompt('Rename shortcut:',s.name);if(nn===null)return;if(nn.trim())s.name=nn.trim();const nu=prompt('URL (Cancel keeps, type DELETE to remove):',s.url);if(nu===null){store.set('shortcuts',shortcuts);renderDock();return;}if(nu.trim().toUpperCase()==='DELETE'){if(confirm(`Delete "${s.name}"?`))shortcuts=shortcuts.filter(x=>x.id!==s.id);}else if(nu.trim())s.url=nu.trim();store.set('shortcuts',shortcuts);renderDock();});}
let dockMagnet=null;
function dockScale(i){if(dockMagnet===null||!store.get('mag',1))return 1;const d=Math.abs(i-dockMagnet);if(d>=1.5)return 1;const t=1-d/1.5;return 1+0.5*t*t;}
function dockMagnify(e){if(!store.get('mag',1))return;if(e.target.closest&&e.target.closest('#dock-grid')){dockMagnet=null;dockReset();return;}const dock=$('#dock');const btns=[...dock.querySelectorAll('a.dock-btn')];if(!btns.length)return;const r0=btns[0].getBoundingClientRect(),r1=btns[btns.length-1].getBoundingClientRect();const pitch=btns.length>1?(r1.left-r0.left)/(btns.length-1):r0.width;dockMagnet=(e.clientX-(r0.left+r0.width/2))/pitch;btns.forEach((b,idx)=>{const k=dockScale(idx);b.style.transform=`scale(${k}) translateY(${-(k-1)*12}px)`;b.style.transformOrigin='bottom center';b.style.transition=dockMagnet===null?'transform .25s cubic-bezier(.2,.8,.2,1)':'transform .08s linear';b.style.zIndex=k>1.05?'2':'';const im=b.querySelector('img');if(im){im.style.width=24*k+'px';im.style.height=24*k+'px';}});}
function dockReset(){dockMagnet=null;$$('#dock a.dock-btn').forEach(b=>{b.style.transform='';b.style.zIndex='';b.style.transition='transform .25s cubic-bezier(.2,.8,.2,1)';const im=b.querySelector('img');if(im){im.style.width='';im.style.height='';}});}
let dragScId=null;
function renderShortcutsList(){const ul=$('#shortcuts-list');if(!ul)return;ul.innerHTML='';shortcuts.forEach(s=>{const li=document.createElement('li');li.className='sc-tile';li.draggable=true;li.dataset.id=s.id;li.innerHTML=`<button class="sc-x" title="Delete">✕</button><span class="tile-name"></span>`;const tic=document.createElement('span');tic.className='tile-ic';paintIcon(tic,s.name,s.url,'');li.insertBefore(tic,li.querySelector('.tile-name'));li.querySelector('.tile-name').textContent=s.name;li.ondragstart=e=>{dragScId=s.id;e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',s.id);}catch{}li.classList.add('dragging');};li.ondragend=()=>{li.classList.remove('dragging');ul.querySelectorAll('.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-before','drop-after'));if(dragScId){const order=[...ul.querySelectorAll('li.sc-tile')].map(x=>x.dataset.id);const map=new Map(shortcuts.map(x=>[x.id,x]));const next=order.map(id=>map.get(id)).filter(Boolean);if(next.length===shortcuts.length){shortcuts=next;store.set('shortcuts',shortcuts);renderDock();}dragScId=null;}};li.onclick=()=>window.open(s.url,'_blank');li.querySelector('.sc-x').onclick=e=>{e.stopPropagation();if(confirm(`Delete "${s.name}"?`)){shortcuts=shortcuts.filter(x=>x.id!==s.id);store.set('shortcuts',shortcuts);renderDock();renderShortcutsList();}};ul.appendChild(li);});ul.ondragover=e=>{e.preventDefault();if(!dragScId)return;const t=e.target.closest('li.sc-tile');if(!t||t.dataset.id===dragScId)return;const r=t.getBoundingClientRect();const after=(e.clientX-r.left)>r.width/2;const cur=ul.querySelector(`li.sc-tile[data-id="${dragScId}"]`);if(!cur||cur===t)return;ul.querySelectorAll('.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-before','drop-after'));t.classList.add(after?'drop-after':'drop-before');if(after)t.parentNode.insertBefore(cur,t.nextSibling);else t.parentNode.insertBefore(cur,t);};ul.ondrop=e=>{e.preventDefault();};}
$('#dock').addEventListener('mousemove',dockMagnify);
$('#dock').addEventListener('mouseleave',dockReset);
$('#shortcut-add').onclick=()=>{const n=$('#shortcut-name').value.trim(),u=$('#shortcut-url').value.trim();if(!n||!u)return;shortcuts.push({id:String(Date.now()),name:n,url:/^https?:\/\//.test(u)?u:'https://'+u,cls:''});$('#shortcut-name').value='';$('#shortcut-url').value='';store.set('shortcuts',shortcuts);renderDock();};
$$('#dock a.dock-btn').forEach(bindDockBtn);
renderDock();

