function moveSetGlider(instant){const nav=$('#settings-modal .set-tabs');if(!nav)return;const modal=$('#settings-modal');if(modal&&modal.classList.contains('hidden'))return;let g=nav.querySelector('.set-glider');if(!g){g=document.createElement('div');g.className='set-glider';nav.prepend(g);}const b=nav.querySelector('button.active')||nav.querySelector('button');if(!b)return;const nr=nav.getBoundingClientRect(),br=b.getBoundingClientRect();if(!br.width||!br.height)return;g.style.opacity='1';if(instant)g.style.transition='none';g.style.left=(br.left-nr.left)+'px';g.style.top=(br.top-nr.top)+'px';g.style.width=br.width+'px';g.style.height=br.height+'px';if(instant){void g.offsetWidth;g.style.transition='';}}
$$('.set-tabs button').forEach(b=>b.onclick=()=>{$$('.set-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.set-pane').forEach(p=>p.classList.remove('active'));const p=$('#pane-'+b.dataset.tab);if(p)p.classList.add('active');syncSettingsTitle(b.dataset.tab);flashSettingsTab();moveSetGlider();});
