const NEWS_COUNTRIES=[['IN','India','en-IN','IN','IN:en'],['US','United States','en-US','US','US:en'],['GB','United Kingdom','en-GB','GB','GB:en'],['CA','Canada','en-CA','CA','CA:en'],['AU','Australia','en-AU','AU','AU:en'],['SG','Singapore','en-SG','SG','SG:en'],['JP','Japan','en','JP','JP:en'],['FR','France','en','FR','FR:en'],['DE','Germany','en','DE','DE:en'],['KR','South Korea','en','KR','KR:en']];
const NEWS_CATS=[['general','General'],['business','Business'],['technology','Technology'],['entertainment','Entertainment'],['sports','Sports'],['science','Science'],['health','Health']];
function newsKey(){return store.get('newsCountry','IN')+'|'+store.get('newsCat','general');}
function newsUrl(fb){const c=NEWS_COUNTRIES.find(x=>x[0]===store.get('newsCountry','IN'))||NEWS_COUNTRIES[0];const cat=store.get('newsCat','general');const geo=`hl=${c[2]}&gl=${c[3]}&ceid=${c[4]}`;const base=cat==='general'?`https://news.google.com/rss?${geo}`:`https://news.google.com/rss/search?q=${encodeURIComponent(cat)}&${geo}`;return fb?base+'&_='+Date.now():base;}
function inlinePick(cfg){const btn=$('#'+cfg.btn),ul=$('#'+cfg.list);if(!btn||!ul)return null;let kbd=-1,key=false;const paint=()=>{const cur=cfg.cur();const found=cfg.options.find(o=>o[0]===cur);const sp=btn.querySelector('span');if(sp)sp.textContent=found?found[1]:cur;ul.innerHTML='';kbd=-1;cfg.options.forEach(([v,label])=>{const li=document.createElement('li');li.textContent=label;if(v===cur)li.classList.add('on');li.onclick=e=>{e.stopPropagation();api.close();cfg.onPick(v);};li.onmousemove=()=>{const i=[...ul.children].indexOf(li);if(i!==kbd){kbd=i;key=false;hl();}};ul.appendChild(li);});};const hl=()=>{[...ul.children].forEach((li,i)=>li.classList.toggle('kbd',i===kbd));if(!key)return;const act=ul.children[kbd];if(act)act.scrollIntoView({block:'nearest'});};const api={paint,close:()=>{ul.classList.remove('open');btn.setAttribute('aria-expanded','false');kbd=-1;},isOpen:()=>ul.classList.contains('open')};btn.onclick=e=>{e.stopPropagation();if(ul.classList.contains('open'))api.close();else{paint();ul.classList.add('open');btn.setAttribute('aria-expanded','true');}};btn.onkeydown=e=>{const cur=cfg.cur();if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();key=true;if(!ul.classList.contains('open')){paint();ul.classList.add('open');}if(kbd<0)kbd=Math.max(0,cfg.options.findIndex(o=>o[0]===cur));kbd=(kbd+(e.key==='ArrowDown'?1:-1)+cfg.options.length)%cfg.options.length;hl();}else if(e.key==='Enter'&&ul.classList.contains('open')){e.preventDefault();const o=cfg.options[kbd];api.close();cfg.onPick(o?o[0]:cur);}else if(e.key==='Escape'){api.close();}};paint();return api;}
let ncPick=null,ntPick=null;
function paintNewsPickers(){ncPick=inlinePick({btn:'nc-btn',list:'nc-list',options:NEWS_COUNTRIES.map(c=>[c[0],c[1]]),cur:()=>store.get('newsCountry','IN'),onPick:v=>{store.set('newsCountry',v);if(ncPick)ncPick.paint();loadNews(true);}});ntPick=inlinePick({btn:'nt-btn',list:'nt-list',options:NEWS_CATS.map(c=>[c[0],c[1]]),cur:()=>store.get('newsCat','general'),onPick:v=>{store.set('newsCat',v);if(ntPick)ntPick.paint();loadNews(true);}});}

async function loadNews(force){const ul=$('#news-list');const key=newsKey();const rb=$('#news-refresh');if(rb)rb.classList.add('spinning');try{if(!force){const nc=store.get('newsCache',null);if(nc&&nc.key===key&&(Date.now()-nc.ts)<216e5&&nc.items&&nc.items.length){paintNews(nc.items,nc.ts);if(rb)rb.classList.remove('spinning');return;}}if(ul)ul.innerHTML='<div class="gh-skel"></div><div class="gh-skel"></div><div class="gh-skel"></div>';const r=await fetch(newsUrl(force));if(!r.ok)throw 0;const t=await r.text();const doc=new DOMParser().parseFromString(t,'text/xml');const items=[...doc.querySelectorAll('item')].slice(0,12).map(it=>{const raw=((it.querySelector('title')||{}).textContent||'').trim();const parts=raw.split(' - ');const srcNode=it.querySelector('source');return{title:(parts[0]||raw).trim(),link:((it.querySelector('link')||{}).textContent||'').trim(),source:((srcNode&&srcNode.textContent)||parts.slice(1).join(' - ')||'News').trim(),ts:((it.querySelector('pubDate')||{}).textContent||'').trim()};}).filter(x=>x.title&&x.link);if(!items.length)throw 0;store.set('newsCache',{key,ts:Date.now(),items});paintNews(items,Date.now());if(force&&rb)flashSaved(rb,'✓');}catch{if(ul)ul.innerHTML='<li style="text-align:center;font-size:12px;opacity:.6">Could not load headlines</li>';}if(rb)rb.classList.remove('spinning');}
function paintNews(items,ts){const ul=$('#news-list');if(!ul)return;ul.innerHTML='';items.forEach(n=>{const li=document.createElement('li');const a=document.createElement('a');a.href=n.link;a.target='_blank';a.rel='noopener';const t=document.createElement('div');t.className='n-title';t.textContent=n.title;const m=document.createElement('div');m.className='n-meta';const s=document.createElement('span');s.textContent=n.source;const tm=document.createElement('span');const p2=n=>String(n).padStart(2,'0');try{const d=new Date(n.ts);tm.textContent=`${p2(d.getHours())}:${p2(d.getMinutes())}, ${p2(d.getDate())}-${p2(d.getMonth()+1)}-${String(d.getFullYear()).slice(2)}`;}catch{tm.textContent=relTime(n.ts);}m.appendChild(s);m.appendChild(tm);a.appendChild(t);a.appendChild(m);li.appendChild(a);ul.appendChild(li);});const up=$('#news-updated');if(up){const d=new Date(ts);const p2=n=>String(n).padStart(2,'0');up.textContent=`Last updated: ${p2(d.getHours())}:${p2(d.getMinutes())}, ${p2(d.getDate())}-${p2(d.getMonth()+1)}-${String(d.getFullYear()).slice(2)}`;}const wn=$('#news-count');if(wn)wn.textContent=items.length;}
paintNewsPickers();loadNews();
