function closeNews(){const p=$('#news-panel');if(p)p.classList.remove('open');const nc=$('#news-notch');if(nc)nc.classList.remove('gone');}
$('#news-notch').onclick=e=>{e.stopPropagation();const p=$('#news-panel');if(p&&p.classList.contains('open'))closeNews();else openNews();};
