/* orbit defaults: two staggered columns flowing down-right (see renderOrbit) */
function renderOrbit(){const o=$('#ai-orbit');if(!o)return;o.innerHTML='';const n=agents.length;let orbOver=store.get('orbit2',{});
function attachOrbitDrag(el,a){el.style.touchAction='none';el.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();try{el.setPointerCapture(e.pointerId);}catch{}const cs=getComputedStyle(el);const cur=el.style;const base=[parseFloat(cur.getPropertyValue('--tx'))||0,parseFloat(cur.getPropertyValue('--ty'))||0];const ox=e.clientX,oy=e.clientY;let moved=false;const move=ev=>{const dx=ev.clientX-ox,dy=ev.clientY-oy;if(!moved&&Math.hypot(dx,dy)>9){moved=true;el.classList.add('dragging');}if(moved){el.style.setProperty('--tx',(base[0]+dx).toFixed(1)+'px');el.style.setProperty('--ty',(base[1]+dy).toFixed(1)+'px');}};const up=ev=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);el.removeEventListener('pointercancel',up);el.classList.remove('dragging');if(moved){const nx=parseFloat(el.style.getPropertyValue('--tx')),ny=parseFloat(el.style.getPropertyValue('--ty'));orbOver[a.id]=[+nx.toFixed(1),+ny.toFixed(1)];store.set('orbit2',orbOver);el.addEventListener('click',ev2=>{ev2.stopPropagation();ev2.preventDefault();},{capture:true,once:true});}};el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);});}
const make=(a,ts,gi)=>{const ov=orbOver[a.id];const p=ov||ts;const el=document.createElement('a');el.className='orbit-btn';el.href=a.url;el.target='_blank';el.rel='noopener';el.title=a.name;el.dataset.aid=a.id;el.style.cssText=`--tx:${(+p[0]).toFixed(1)}px;--ty:${(+p[1]).toFixed(1)}px;transition-delay:${30+gi*45}ms`;paintIcon(el,a.name,a.url,'olet');attachOrbitDrag(el,a);o.appendChild(el);};let gi=0;const og=Object.assign({r:135,size:45,gap:55},store.get('orbitGeom',{}));const oel=$('#ai-orbit');if(oel)oel.style.setProperty('--os',og.size+'px');const R=og.r,r1=Math.max(60,R-(+og.gap||55)),A0=2,A1=92,na=Math.floor(n/2),nb=n-na;const spread=(r,k,off)=>{const p=[];for(let i=0;i<k;i++){const ang=(A0+(A1-A0)*(k===1?0.5:(i+off)/(k-(off?0:1))))*Math.PI/180;p.push([r*Math.cos(ang),r*Math.sin(ang)]);}return p;};const ptsA=spread(r1,na,0),ptsB=spread(R,nb,0.5);agents.slice(0,na).forEach((a,i)=>make(a,ptsA[i],gi++));agents.slice(na).forEach((a,i)=>make(a,ptsB[i],gi++));}
function renderOrbitGeom(){const g=$('#orbit-geom');if(!g)return;g.innerHTML='';if(store.get('geomV',0)!==3){store.set('geomV',3);store.set('orbitGeom',{r:135,size:45,gap:55});}const og=Object.assign({r:135,size:45,gap:55},store.get('orbitGeom',{}));const save=()=>{store.set('orbitGeom',og);renderOrbit();};g.appendChild(sliderRow('Fan radius','How far the arc reaches from the button',120,240,5,og.r,v=>v+'px',v=>{og.r=v;save();}));g.appendChild(sliderRow('Orb size','Diameter of the satellite buttons',36,60,2,og.size,v=>v+'px',v=>{og.size=v;save();}));g.appendChild(sliderRow('Row distance','Gap in pixels between the two rows',50,110,1,og.gap,v=>v+'px',v=>{og.gap=v;save();}));}
