function buildHolList(){const ul=$('#hol-list');if(!ul)return;const cur=store.get('holiday','India');ul.innerHTML='';holKbd=-1;HOLIDAY_COUNTRIES.forEach(c=>{const li=document.createElement('li');li.textContent=c;li.setAttribute('role','option');if(c===cur)li.classList.add('on');li.onclick=e=>{e.stopPropagation();selectHoliday(c);};li.onmousemove=()=>{const i=[...ul.children].indexOf(li);if(i!==holKbd){holKbd=i;holNavKey=false;paintHolKbd();}};ul.appendChild(li);});}
