let onbNews=1,onbGh=0;
function onbShould(){try{return store.get('onb',1)===0;}catch{return false;}}
function onbCloseAll(){const g=$('#onb-guide'),w=$('#onb-wiz');if(g)g.classList.add('hidden');if(w)w.classList.add('hidden');}
function onbPaintSegs(){[['onb-news-seg',onbNews],['onb-gh-seg',onbGh]].forEach(([id,v])=>{[...document.querySelectorAll('#'+id+' button')].forEach(b=>b.classList.toggle('on',+b.dataset.v===v));});const ne=$('#onb-news-extra');if(ne)ne.classList.toggle('hidden',!onbNews);const ge=$('#onb-gh-extra');if(ge)ge.classList.toggle('hidden',!onbGh);}
function onbInitWizard(){
const cc=$('#onb-news-country');if(cc){cc.innerHTML='';NEWS_COUNTRIES.forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;cc.appendChild(o);});try{cc.value=store.get('newsCountry','US');}catch{}}
const ct=$('#onb-news-cat');if(ct){ct.innerHTML='';NEWS_CATS.forEach(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;ct.appendChild(o);});try{ct.value=store.get('newsCat','general');}catch{}}
const hc=$('#onb-holiday');if(hc){hc.innerHTML='';HOLIDAY_COUNTRIES.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;hc.appendChild(o);});try{hc.value=store.get('holiday','General');}catch{}}
onbPaintSegs();
[...document.querySelectorAll('#onb-news-seg button')].forEach(b=>b.onclick=()=>{onbNews=+b.dataset.v;onbPaintSegs();});
[...document.querySelectorAll('#onb-gh-seg button')].forEach(b=>b.onclick=()=>{onbGh=+b.dataset.v;onbPaintSegs();});
}
async function onbGeocode(city,cc){const r=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1${cc?'&countryCode='+encodeURIComponent(cc):''}`);const j=await r.json();return(j.results&&j.results[0])||null;}
async function onbIp(){
const seq=[['https://ipwho.is/',j=>({city:j.city,cc:j.country_code})],['https://ipapi.co/json/',j=>({city:j.city,cc:j.country_code})],['https://freeipapi.com/api/json/',j=>({city:j.cityName,cc:j.countryCode})],['https://get.geojs.io/v1/ip/geo.json',j=>({city:j.city,cc:j.country_code})]];
for(const[u,map]of seq){try{const ctl=new AbortController();const t=setTimeout(()=>{try{ctl.abort();}catch{}},5000);const r=await fetch(u,{signal:ctl.signal});clearTimeout(t);if(!r.ok)continue;const j=await r.json();const m=(map(j)||{});const city=(m.city||'').trim(),cc=(m.cc||'').trim().toUpperCase();if(city&&cc)return{city,cc};}catch{}}
return null;
}
function onbNote(id,msg,ok){const e=$(id);if(!e)return;if(!msg){e.textContent='';e.className='onb-err hidden';}else{e.textContent=(ok?'\u2713 ':'')+msg;e.className=ok?'onb-ok':'onb-err';}}
let onbCityCache={v:null,geo:null},onbGhCache={v:null,ok:false,login:''},onbCityT=null,onbGhT=null;
function onbLiveCity(){const ci=$('#onb-city');if(!ci)return;onbCityCache={v:null,geo:null};onbNote('#onb-city-err','');clearTimeout(onbCityT);const v=ci.value.trim();if(!v)return;onbCityT=setTimeout(async()=>{try{if(ci.value.trim()!==v)return;}catch{return;}let geo=null;try{geo=await onbGeocode(v);}catch{}try{if(ci.value.trim()!==v)return;}catch{return;}if(geo){onbCityCache={v,geo};onbNote('#onb-city-err',geo.name||v,true);}},700);}
function onbLiveGh(){const gu=$('#onb-gh-user');if(!gu||!onbGh)return;onbGhCache={v:null,ok:false,login:''};onbNote('#onb-gh-err','');clearTimeout(onbGhT);const v=gu.value.trim();if(!v)return;onbGhT=setTimeout(async()=>{try{if(gu.value.trim()!==v||!onbGh)return;}catch{return;}let login='';try{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(v)}`);if(r.status===200){try{login=(await r.json()).login||v;}catch{login=v;}}}catch{}try{if(gu.value.trim()!==v||!onbGh)return;}catch{return;}if(login){onbGhCache={v,ok:true,login};onbNote('#onb-gh-err','@'+login,true);}},700);}
function onbApplyCommon(){
const nc=$('#onb-news-country'),nt=$('#onb-news-cat'),hc=$('#onb-holiday');
if(onbNews&&nc)store.set('newsCountry',nc.value||'US');if(onbNews&&nt)store.set('newsCat',nt.value||'general');
if(hc)store.set('holiday',hc.value||'General');
try{vis.news=onbNews?1:0;store.set('vis',vis);applyVis();renderToggles();}catch{}
try{paintNewsPickers();loadNews();paintHoliday();renderCal();}catch{}
}
async function onbFinish(){
if(!onbShould()){onbCloseAll();return;}
const btn=$('#onb-next');if(btn){btn.disabled=true;btn.textContent='Checking…';}
const restore=()=>{if(btn){btn.disabled=false;btn.textContent='Continue';}};
clearTimeout(onbCityT);clearTimeout(onbGhT);
onbNote('#onb-city-err','');onbNote('#onb-gh-err','');
const city=(($('#onb-city')||{}).value||'').trim();
if(!city){onbNote('#onb-city-err','Enter your city');try{$('#onb-city').focus();}catch{}restore();return;}
let geo=(onbCityCache.v===city&&city)?onbCityCache.geo:null;
if(!geo){try{geo=await onbGeocode(city);}catch{}}
if(!geo){onbNote('#onb-city-err','City not found — try another name');restore();return;}
onbCityCache={v:city,geo};onbNote('#onb-city-err',geo.name||city,true);
let ghU='';
if(onbGh){
ghU=(($('#onb-gh-user')||{}).value||'').trim();
if(!ghU){onbNote('#onb-gh-err','Enter your GitHub username');restore();return;}
if(!(onbGhCache.v===ghU&&onbGhCache.ok)){
let st=0,net=false,login='';try{const r=await fetch(`https://api.github.com/users/${encodeURIComponent(ghU)}`);st=r.status;if(st===200){try{login=(await r.json()).login||ghU;}catch{login=ghU;}}}catch{net=true;}
if(net){onbNote('#onb-gh-err',"Couldn't verify — check connection");restore();return;}
if(st===404){onbNote('#onb-gh-err','User not found');restore();return;}
if(st===403){onbNote('#onb-gh-err','Rate limited — wait a minute or choose No');restore();return;}
if(st!==200){onbNote('#onb-gh-err',"Couldn't verify — check connection");restore();return;}
onbGhCache={v:ghU,ok:true,login:login||ghU};
}
onbNote('#onb-gh-err','@'+(onbGhCache.login||ghU),true);
}
try{wx.city=(geo.name||city);wx.mode='city';store.set('weather',wx);wxSync();wxSyncSettings();loadWeather();}catch{store.set('weather',Object.assign(store.get('weather',{}),{city:geo.name||city,mode:'city'}));}
if(onbGh){try{ghUser=ghU;store.set('gh',ghU);ghSel={repo:'',branch:'',defBranch:''};store.set('ghSel',ghSel);ghSyncInputs();loadGH();loadGhRepos().catch(()=>{});}catch{store.set('gh',ghU);}}
else{try{vis.github=0;}catch{}}
onbApplyCommon();
store.set('onb',1);restore();onbCloseAll();
}
let onbBusy=false;
async function onbSkip(){
if(onbBusy||!onbShould())return;onbBusy=true;
const btn=$('#onb-skip');const old=btn?btn.textContent:'';if(btn)btn.textContent='Detecting…';
const finish=()=>{onbBusy=false;if(btn)btn.textContent=old;};
onbNote('#onb-city-err','');
const ip=await onbIp();
try{vis.github=0;vis.news=1;store.set('vis',vis);applyVis();renderToggles();}catch{}
if(!ip){
store.set('newsCountry','US');store.set('newsCat','general');store.set('holiday','General');
try{paintNewsPickers();loadNews();paintHoliday();renderCal();}catch{}
onbInitWizard();
onbNote('#onb-city-err',"Couldn't detect location — enter your city");
finish();return;
}
const cc=(ip.cc||'').toUpperCase();
store.set('newsCountry',NEWS_COUNTRIES.some(x=>x[0]===cc)?cc:'US');store.set('newsCat','general');
const CC2HOL={IN:'India',US:'United States',GB:'United Kingdom',CA:'Canada',AU:'Australia',DE:'Germany',FR:'France',JP:'Japan'};
store.set('holiday',CC2HOL[cc]||'General');
let geo=null;try{geo=await onbGeocode(ip.city,cc);}catch{}
if(geo&&geo.name){
try{wx.city=geo.name;wx.mode='city';store.set('weather',wx);wxSync();wxSyncSettings();loadWeather();}catch{store.set('weather',Object.assign(store.get('weather',{}),{city:geo.name,mode:'city'}));}
try{paintNewsPickers();loadNews();paintHoliday();renderCal();}catch{}
store.set('onb',1);finish();onbCloseAll();return;
}
onbInitWizard();
try{const ci=$('#onb-city');if(ci)ci.value=ip.city;}catch{}
onbNote('#onb-city-err','We found \u201C'+ip.city+'\u201D — confirm your city',true);
try{paintNewsPickers();loadNews();paintHoliday();renderCal();}catch{}
finish();
}
(function(){
if(!onbShould())return;
onbNews=1;onbGh=0;
onbInitWizard();
const g=$('#onb-guide');if(g)g.classList.remove('hidden');
const d=$('#onb-done');if(d)d.onclick=()=>{if(g)g.classList.add('hidden');const w=$('#onb-wiz');if(w)w.classList.remove('hidden');try{const ci=$('#onb-city');if(ci)ci.focus();}catch{}};
const n=$('#onb-next');if(n)n.onclick=()=>onbFinish();
const s=$('#onb-skip');if(s)s.onclick=()=>onbSkip();
const ci=$('#onb-city');if(ci){ci.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();onbFinish();}};ci.addEventListener('input',onbLiveCity);}
const gu=$('#onb-gh-user');if(gu){gu.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();onbFinish();}};gu.addEventListener('input',onbLiveGh);}
})();